class Trie:
    def __init__(self):
        self.ch = {}; self.end = False
    def insert(self, w):
        n = self
        for c in w:
            if c not in n.ch: n.ch[c] = Trie()
            n = n.ch[c]
        n.end = True
    def search(self, w):
        n = self._find(w)
        return bool(n and n.end)
    def startsWith(self, p):
        return self._find(p) is not None
    def _find(self, w):
        n = self
        for c in w:
            if c not in n.ch: return None
            n = n.ch[c]
        return n

class Trie:
    def __init__(self):
        self.kids = [None]*26; self.end = False
    def insert(self, w):
        n = self
        for c in w:
            i = ord(c) - 97
            if not n.kids[i]: n.kids[i] = Trie()
            n = n.kids[i]
        n.end = True
    def search(self, w):
        n = self._f(w)
        return bool(n and n.end)
    def startsWith(self, p):
        return self._f(p) is not None
    def _f(self, w):
        n = self
        for c in w:
            n = n.kids[ord(c)-97]
            if not n: return None
        return n

class WordDictionary:
    def __init__(self):
        self.ch = {}; self.end = False
    def addWord(self, w):
        n = self
        for c in w:
            if c not in n.ch: n.ch[c] = WordDictionary()
            n = n.ch[c]
        n.end = True
    def search(self, w):
        def dfs(i, n):
            if i == len(w): return n.end
            c = w[i]
            if c != '.':
                return c in n.ch and dfs(i+1, n.ch[c])
            return any(dfs(i+1, k) for k in n.ch.values())
        return dfs(0, self)

