def find_words(board, words):
    root = Trie()
    for w in words: root.add(w)
    m, n = len(board), len(board[0]); res = set()
    def dfs(i, j, node):
        if i < 0 or i >= m or j < 0 or j >= n: return
        c = board[i][j]
        if c not in node.kids: return
        node = node.kids[c]
        if node.word: res.add(node.word)
        board[i][j] = '#'
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)): dfs(i+di, j+dj, node)
        board[i][j] = c
    for i in range(m):
        for j in range(n): dfs(i, j, root)
    return list(res)
